from pathlib import Path
import html,json
root=Path('artifacts/juice')
vehicles=[('vela-gt','Vela GT','Low coupe, wide rear haunches, projector lamps and a rear diffuser.'),('traffic-sedan','Coastal sedan','Long hood and separate trunk, chrome bumper and eight-spoke wheels.'),('traffic-wagon','Surf wagon','Long cargo body, upright tailgate, roof rails and split-spoke wheels.'),('traffic-compact','Compact','Short hatchback, rounded lamps, small wheels and a rear spoiler.'),('traffic-pickup','Pickup','Raised hood, steel bumpers, truck tires and an open ribbed cargo bed.'),('traffic-camper','Weekend camper','Short van nose, full-height sides, rear door and a two-tone pop-top roof.')]
scenery=[('last-light-station','Last Light station'),('horizon-lodge','Horizon Motor Lodge'),('pacific-point','Pacific Point lighthouse'),('pacific-palm','Coastal palm'),('pacific-redwood','Redwood'),('pacific-overlook','Pacific overlook')]
cards=''
for key,label,description in vehicles:
 cards+=f'<article class="card vehicle" data-model="{key}"><a class="study" href="vehicles-v2/{key}-front.png"><img class="current" src="vehicles-v2/{key}-front.png?v=lighting3" alt="{html.escape(label)} front view"></a><div class="caption"><strong>{label}</strong><p>{description}</p><nav aria-label="{label} views">'+''.join(f'<button data-angle="{angle}" aria-pressed="{str(angle=="front").lower()}">{angle.title()}</button>' for angle in ['front','side','rear'])+f'</nav><details><summary>Previous model</summary><a href="vehicle-before/{key}.png"><img src="vehicle-before/{key}.png" loading="lazy" alt="Previous {label}"></a></details></div></article>'
landmarks=''.join(f'<a class="card" href="model-details/{key}.png"><img src="model-details/{key}.png" loading="lazy" alt="{label}"><span>{label}</span></a>' for key,label in scenery)
colors=''
paint_path=root/'vehicle-colors/paints.json'
if paint_path.exists():
 paints=json.loads(paint_path.read_text())
 for key,label,_ in vehicles[1:]:
  colors+=f'<h3>{label}</h3><div class="paints">'
  for paint in paints:
   if 'traffic-'+paint['kind']!=key:continue
   name=html.escape(paint['name']);file=paint['file'];color=f"{paint['color']:06x}"
   colors+=f'<a class="card" href="vehicle-colors/{file}"><img src="vehicle-colors/{file}" loading="lazy" alt="{name} {label}"><span><i style="background:#{color}"></i>{name}</span></a>'
  colors+='</div>'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pacific Run · vehicle studies</title><style>
*{box-sizing:border-box}body{margin:0;background:#122124;color:#edead9;font:16px/1.6 system-ui}main{max-width:1440px;margin:auto;padding:42px 30px}h1{font:500 48px/1.15 Georgia;margin:4px 0 16px}p{color:#a9bbb6;max-width:790px}small{letter-spacing:.18em;color:#d3ac6c;text-transform:uppercase}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;margin-top:30px}.card{display:block;text-decoration:none;color:inherit;background:#1c2e32;border:1px solid #344647;border-radius:8px;overflow:hidden}.card img{display:block;width:100%;aspect-ratio:1.4;object-fit:cover}.card span,.caption{display:block;padding:12px 16px}.caption strong{font-size:20px;font-weight:500}.caption p{font-size:14px;line-height:1.55;margin:7px 0 14px;min-height:44px}.caption nav{display:flex;gap:8px}button{font:inherit;color:#c6d4cf;background:#14252a;border:1px solid #465453;padding:5px 12px;border-radius:4px;cursor:pointer}button[aria-pressed=true]{border-color:#d3ac6c;color:#efd7af}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #efd7af;outline-offset:4px}details{margin-top:12px;font-size:13px;color:#acbbb6}summary{cursor:pointer}details img{margin-top:12px;border-radius:4px}.paints{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.paints span{font-size:13px;padding:10px 12px}.paints i{display:inline-block;width:12px;height:12px;border:1px solid #eee8;border-radius:50%;margin-right:8px;vertical-align:-1px}.sky{display:grid;grid-template-columns:1fr 1fr;gap:22px}.sky img{width:100%;display:block}h2{margin-top:48px;font-weight:500}h3{font-size:18px;font-weight:500;margin:26px 0 12px}a{color:#e9c689}.gallery-nav{display:flex;gap:25px;flex-wrap:wrap}@media(max-width:1000px){.paints{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:800px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sky{grid-template-columns:1fr}h1{font-size:36px}main{padding:30px 18px}.paints{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.grid{grid-template-columns:1fr}}
</style><main><small>Pacific Run · vehicle collection</small><h1>A different character in every lane.</h1><p>Six complete vehicle designs, with their own proportions, fenders, bumpers, wheels and rear bodies. Switch views to inspect each shape, or open the previous model for a comparison.</p><nav class="gallery-nav"><a href="/">Return to the game →</a><a href="/artifacts/world-life/world-gallery.html">Explore the living coast →</a><a href="/artifacts/road-land/road-gallery.html">Explore the road & land →</a><a href="/artifacts/water/water-gallery.html">Explore the water →</a><a href="#colors">Explore the colors ↓</a><a href="#lighting">Compare the lighting ↓</a></nav><div class="grid">'''+cards+'''</div><h2 id="colors">More color for the coast</h2><p>Ten paint choices now appear in the garage and across moving and parked traffic. The camper carries a coordinated pale upper body and roof. Here are five color studies for each traffic vehicle.</p>'''+colors+'''<h2 id="lighting">Gentler light, richer detail</h2><p>Softer sunlight and reflections preserve the paint finish, while restrained bloom keeps bright trim and the horizon clear.</p><div class="sky"><a class="card" href="lighting-before/high-coast.png"><img src="lighting-before/high-coast.png" loading="lazy" alt="Coastal drive before the lighting adjustment"><span>Before · coastal drive</span></a><a class="card" href="lighting-after/high-coast.png"><img src="lighting-after/high-coast.png" loading="lazy" alt="Coastal drive with softer lighting"><span>After · coastal drive</span></a><a class="card" href="lighting-before/traffic-sedan-studio.png"><img src="lighting-before/traffic-sedan-studio.png" loading="lazy" alt="Sedan under the previous studio lighting"><span>Before · studio lighting</span></a><a class="card" href="vehicles-v2/traffic-sedan-front.png"><img src="vehicles-v2/traffic-sedan-front.png?v=lighting3" loading="lazy" alt="Sedan under the softer studio lighting"><span>After · studio lighting</span></a></div><h2>Along the drive</h2><div class="grid">'''+landmarks+'''</div><h2>A living Pacific sky</h2><p>The same camera, two minutes apart. Clouds travel on the wind as sunlight changes direction and softens under cloud cover.</p><div class="sky"><a href="model-details/sky-start.png"><img src="model-details/sky-start.png" loading="lazy" alt="Atmosphere at the beginning"></a><a href="model-details/sky-later.png"><img src="model-details/sky-later.png" loading="lazy" alt="Atmosphere after two minutes"></a></div><h2>Back on the road</h2><div class="sky"><a href="lighting-after/high-forest.png"><img src="lighting-after/high-forest.png" loading="lazy" alt="Softer sunlight through the redwoods"></a><a href="lighting-after/high-sunset.png"><img src="lighting-after/high-sunset.png" loading="lazy" alt="Evening coast under the adjusted lighting"></a></div></main><script>
document.querySelectorAll('.vehicle').forEach(card=>card.querySelectorAll('[data-angle]').forEach(button=>button.addEventListener('click',()=>{const angle=button.dataset.angle,model=card.dataset.model,img=card.querySelector('.current'),link=card.querySelector('.study');img.src=`vehicles-v2/${model}-${angle}.png?v=lighting3`;img.alt=`${card.querySelector('strong').textContent} ${angle} view`;link.href=img.src;card.querySelectorAll('[data-angle]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));})));
</script></html>'''
(root/'detail-gallery.html').write_text(page,encoding='utf8')
